    for r in range(h):
        for c in range(w):
            if grid[r][c]!=2: continue
            marked=False
            for comp in comps:
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                if r0<=r<=r1 and c0<=c<=c1:
